-- Run in a FRESH Supabase project. This schema replaces the original prototype schema.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default 'Student',email text not null,role text not null default 'student' check(role in ('student','teacher','admin')),created_at timestamptz not null default now());
create table public.courses(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references public.profiles(id),title text not null,description text not null default '',status text not null default 'draft' check(status in ('draft','published')),created_at timestamptz default now());
create table public.enrollments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,course_id uuid not null references public.courses(id) on delete cascade,created_at timestamptz default now(),unique(student_id,course_id));
create table public.lessons(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,body text not null default '',video_url text,position int generated by default as identity,created_at timestamptz default now());
create table public.lesson_progress(student_id uuid not null references public.profiles(id) on delete cascade,lesson_id uuid not null references public.lessons(id) on delete cascade,completed_at timestamptz not null default now(),primary key(student_id,lesson_id));
create table public.quizzes(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,created_at timestamptz default now());
create table public.quiz_questions(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,question text not null,options jsonb not null,correct_index integer not null check(correct_index between 0 and 3));
create table public.quiz_attempts(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,student_id uuid not null references public.profiles(id),selected_index int not null,correct boolean not null,created_at timestamptz default now());
create table public.assignments(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,description text not null default '',due_at timestamptz);
create table public.assignment_submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments(id) on delete cascade,student_id uuid not null references public.profiles(id),answer text not null,score numeric,feedback text,created_at timestamptz default now(),unique(assignment_id,student_id));
-- SECURITY DEFINER helpers bypass RLS only for these boolean checks. The locked search_path avoids name hijacking.
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin')$$;
create function public.is_teacher(course uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.courses c where c.id=course and (c.teacher_id=(select auth.uid()) or public.is_admin()))$$;
create function public.is_enrolled(course uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.enrollments e where e.course_id=course and e.student_id=(select auth.uid()))$$;
create function public.can_access_course(course uuid) returns boolean language sql stable security definer set search_path='' as $$select public.is_teacher(course) or (public.is_enrolled(course) and exists(select 1 from public.courses c where c.id=course and c.status='published'))$$;
create function public.can_access_quiz(qid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.quizzes q where q.id=qid and public.can_access_course(q.course_id))$$;
create function public.can_access_lesson(lid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.lessons l where l.id=lid and public.can_access_course(l.course_id))$$;
create function public.is_student() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='student')$$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,full_name,email,role) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'full_name',''),'Student'),coalesce(new.email,''),'student');return new;end$$;
create trigger auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
-- never let users change their own role/email with direct updates
create function public.guard_profile_update() returns trigger language plpgsql set search_path='' as $$begin if current_user not in ('postgres','service_role','supabase_admin') and (new.role is distinct from old.role or new.email is distinct from old.email or new.id is distinct from old.id) then raise exception 'Protected profile fields';end if;return new;end$$;
create trigger protect_profile before update on public.profiles for each row execute function public.guard_profile_update();
-- Restrict access for ALL tables (including attempts/questions) with database RLS.
alter table public.profiles enable row level security;
alter table public.courses enable row level security;
alter table public.enrollments enable row level security;
alter table public.lessons enable row level security;
alter table public.lesson_progress enable row level security;
alter table public.quizzes enable row level security;
alter table public.quiz_questions enable row level security;
alter table public.quiz_attempts enable row level security;
alter table public.assignments enable row level security;
alter table public.assignment_submissions enable row level security;
create policy profile_read on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_admin() or exists(select 1 from public.courses c where c.teacher_id=(select auth.uid()) and exists(select 1 from public.enrollments e where e.course_id=c.id and e.student_id=profiles.id)));
create policy profile_edit on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy course_read on public.courses for select to authenticated using(public.can_access_course(id));
create policy course_write on public.courses for insert to authenticated with check((teacher_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='teacher')) or public.is_admin());
create policy course_update on public.courses for update to authenticated using(public.is_teacher(id)) with check(public.is_teacher(id));
create policy course_delete on public.courses for delete to authenticated using(public.is_teacher(id));
create policy enrollment_read on public.enrollments for select to authenticated using(student_id=(select auth.uid()) or public.is_teacher(course_id));
create policy enrollment_write on public.enrollments for insert to authenticated with check(public.is_teacher(course_id) and exists(select 1 from public.profiles p where p.id=student_id and p.role='student'));
create policy enrollment_delete on public.enrollments for delete to authenticated using(public.is_teacher(course_id));
create policy lesson_read on public.lessons for select to authenticated using(public.can_access_course(course_id));
create policy lesson_insert on public.lessons for insert to authenticated with check(public.is_teacher(course_id));
create policy lesson_update on public.lessons for update to authenticated using(public.is_teacher(course_id)) with check(public.is_teacher(course_id));
create policy lesson_delete on public.lessons for delete to authenticated using(public.is_teacher(course_id));
create policy progress_read on public.lesson_progress for select to authenticated using(student_id=(select auth.uid()) or public.can_access_lesson(lesson_id) and exists(select 1 from public.lessons l where l.id=lesson_id and public.is_teacher(l.course_id)));
create policy progress_write on public.lesson_progress for insert to authenticated with check(student_id=(select auth.uid()) and public.is_student() and public.can_access_lesson(lesson_id));
create policy progress_delete on public.lesson_progress for delete to authenticated using(student_id=(select auth.uid()));
create policy quiz_read on public.quizzes for select to authenticated using(public.can_access_course(course_id));
create policy quiz_write on public.quizzes for insert to authenticated with check(public.is_teacher(course_id));
create policy quiz_delete on public.quizzes for delete to authenticated using(public.is_teacher(course_id));
-- Students may read quiz questions, but NEVER their answer key. Expose questions via dedicated safe view instead.
create policy question_staff_read on public.quiz_questions for select to authenticated using(exists(select 1 from public.quizzes q where q.id=quiz_id and public.is_teacher(q.course_id)));
create policy question_write on public.quiz_questions for insert to authenticated with check(exists(select 1 from public.quizzes q where q.id=quiz_id and public.is_teacher(q.course_id)));
create policy question_delete on public.quiz_questions for delete to authenticated using(exists(select 1 from public.quizzes q where q.id=quiz_id and public.is_teacher(q.course_id)));
create policy attempt_read on public.quiz_attempts for select to authenticated using(student_id=(select auth.uid()) or exists(select 1 from public.quizzes q where q.id=quiz_id and public.is_teacher(q.course_id)));
-- Quiz attempts use SECURITY DEFINER RPC below, never client-side score assignment.
create policy assignment_read on public.assignments for select to authenticated using(public.can_access_course(course_id));
create policy assignment_write on public.assignments for insert to authenticated with check(public.is_teacher(course_id));
create policy assignment_delete on public.assignments for delete to authenticated using(public.is_teacher(course_id));
create policy submission_read on public.assignment_submissions for select to authenticated using(student_id=(select auth.uid()) or exists(select 1 from public.assignments a where a.id=assignment_id and public.is_teacher(a.course_id)));
create policy submission_insert on public.assignment_submissions for insert to authenticated with check(student_id=(select auth.uid()) and exists(select 1 from public.assignments a where a.id=assignment_id and public.is_enrolled(a.course_id)));
create policy submission_update on public.assignment_submissions for update to authenticated using(exists(select 1 from public.assignments a where a.id=assignment_id and public.is_teacher(a.course_id))) with check(exists(select 1 from public.assignments a where a.id=assignment_id and public.is_teacher(a.course_id)));
-- Safe quiz response and grading, without leaking correct_index to students.
create function public.get_quiz_question(qid uuid) returns table(question_id uuid,question text,options jsonb) language sql stable security definer set search_path='' as $$select qq.id,qq.question,qq.options from public.quiz_questions qq where qq.quiz_id=qid and public.can_access_quiz(qid)$$;
create function public.submit_quiz_answer(qid uuid,answer_index int) returns boolean language plpgsql security definer set search_path='' as $$declare expected int;is_correct boolean;begin if not public.is_student() or not public.can_access_quiz(qid) then raise exception 'Not authorized';end if;if answer_index not between 0 and 3 then raise exception 'Invalid choice';end if;select qq.correct_index into expected from public.quiz_questions qq where qq.quiz_id=qid limit 1;if expected is null then raise exception 'Quiz has no question';end if;is_correct:=expected=answer_index;insert into public.quiz_attempts(quiz_id,student_id,selected_index,correct) values(qid,auth.uid(),answer_index,is_correct);return is_correct;end$$;
revoke all on function public.get_quiz_question(uuid) from public;
revoke all on function public.submit_quiz_answer(uuid,int) from public;
grant execute on function public.get_quiz_question(uuid) to authenticated;
grant execute on function public.submit_quiz_answer(uuid,int) to authenticated;
create index enroll_course on public.enrollments(course_id);
create index lessons_course on public.lessons(course_id);
create index quiz_course on public.quizzes(course_id);
-- After creating a trusted teacher account, promote explicitly as DB administrator:
-- UPDATE public.profiles SET role='teacher' WHERE email='teacher@example.com';
-- UPDATE public.profiles SET role='admin' WHERE email='you@example.com';

-- Teachers cannot enumerate all profiles. Enrollment by email is a narrow, audited RPC.
create function public.enroll_student_by_email(target_course uuid, target_email text)
returns uuid language plpgsql security definer set search_path='' as $$
declare sid uuid;
begin
 if not public.is_teacher(target_course) then raise exception 'Not authorized'; end if;
 select p.id into sid from public.profiles p where lower(p.email)=lower(trim(target_email)) and p.role='student' limit 1;
 if sid is null then raise exception 'Student must register first'; end if;
 insert into public.enrollments(student_id,course_id) values(sid,target_course) on conflict(student_id,course_id) do nothing;
 return sid;
end$$;
revoke all on function public.enroll_student_by_email(uuid,text) from public;
grant execute on function public.enroll_student_by_email(uuid,text) to authenticated;
